<!doctype html><html lang="en"><head><meta charset="utf-8"><style>@page{margin:32px}body{font-family:DejaVu Sans,sans-serif;color:#122033;font-size:12px}header{border-bottom:3px solid #078a68;padding-bottom:18px;margin-bottom:28px}h1{font-size:27px;margin:0}h2{font-size:16px;margin:22px 0 8px}.meta{width:100%;margin-bottom:24px}.meta td{vertical-align:top;width:50%}table.items{border-collapse:collapse;width:100%;margin-top:18px}.items th,.items td{border-bottom:1px solid #d8e0e8;padding:9px;text-align:left}.items .number{text-align:right}.totals{margin-left:auto;margin-top:18px;width:45%}.totals td{padding:5px}.totals td:last-child{text-align:right}.total{font-size:16px;font-weight:600;color:#078a68}.muted{color:#66758a}.terms{margin-top:28px;white-space:pre-wrap}</style></head><body><header><p class="muted">{{ $quotation->number }}</p><h1>{{ $quotation->currentRevision->title }}</h1></header><table class="meta"><tr><td><strong>Prepared for</strong><br>{{ $quotation->customer->name }}<br>{{ $quotation->customer->email }}</td><td><strong>Issue date</strong> {{ $quotation->issue_date->format('M j, Y') }}<br><strong>Expiry date</strong> {{ $quotation->expiry_date->format('M j, Y') }}<br><strong>Currency</strong> {{ $quotation->currency }}</td></tr></table>@if($quotation->currentRevision->introduction)<p>{{ $quotation->currentRevision->introduction }}</p>@endif<table class="items"><thead><tr><th>Description</th><th class="number">Qty</th><th class="number">Unit price</th><th class="number">Total</th></tr></thead><tbody>@foreach($quotation->currentRevision->items as $item)<tr><td><strong>{{ $item->name }}</strong><br><span class="muted">{{ $item->description }}</span></td><td class="number">{{ rtrim(rtrim($item->quantity,'0'),'.') }}</td><td class="number">{{ number_format($item->unit_price_minor/100,2) }}</td><td class="number">{{ number_format($item->line_total_minor/100,2) }}</td></tr>@endforeach</tbody></table><table class="totals"><tr><td>Subtotal</td><td>{{ number_